protocol LampDelegate: AnyObject { func didChange() }
final class LampRemote {
    weak var delegate: (any LampDelegate)?
    func signal() { delegate?.didChange() }
}
final class Receiver: LampDelegate {
    func didChange() { print("Свет включён") }
}
let remote = LampRemote()
let receiver = Receiver()
remote.delegate = receiver
withExtendedLifetime(receiver) { remote.signal() }

Вывод «Свет включён». У получателя есть сильный владелец на время события; weak остаётся обратной связью.

