final class PlanetModel {
    let id = 6
    func makeAction() -> () -> Void {
        { [weak self] in
            guard let self else { print("Модель удалена"); return }
            print(self.id)
        }
    }
}
var model: PlanetModel? = PlanetModel()
let action = model!.makeAction()
model = nil
action()

Вывод «Модель удалена». Сохранённая кнопка не имеет гарантии жизни модели.

