final class ChessMatch {
    let id = 7
    func makeHistoryAction() -> () -> Void {
        { [id = self.id] in print(id) }
    }
    deinit { print("Партия освобождена") }
}
var match: ChessMatch? = ChessMatch()
let action = match!.makeHistoryAction()
match = nil
action()

Вывод «Партия освобождена», 7. Действию нужен снимок Int, а не живой объект партии.
